const clientName = String(
  $('When Executed by Another Workflow').first().json['Client Name'] || ''
).trim();

if (!clientName) {
  return [{ json: { error: 'Missing Client Name', matched: false } }];
}

const raw = $input.first().json;
const orgs = Array.isArray(raw)
  ? raw
  : Array.isArray(raw?.data)
    ? raw.data
    : $input.all().map((i) => i.json);

const normalize = (name) =>
  String(name || '')
    .toLowerCase()
    .replace(/\s*\[\d+\]\s*$/g, '') // strip " [6103]"
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const target = normalize(clientName);

const match = orgs.find((org) => {
  const orgName = normalize(org.organization_name);
  return orgName === target || orgName.includes(target) || target.includes(orgName);
});

if (!match) {
  return [{
    json: {
      matched: false,
      client_name: clientName,
      error: `No DropSuite org found for "${clientName}"`,
    },
  }];
}

return [{
  json: {
    matched: true,
    client_name: clientName,
    organization_name: match.organization_name,
    organization_id: match.organization_id,
    admin_email: match.email,
    active_seats: match.active_seats ?? 0,
    seats_used: match.seats_used ?? 0,
    seats_available: match.seats_available ?? 0,
    required_seats: match.required_seats ?? 0,
    deactivated_seats: match.deactivated_seats ?? 0,
    storage_used: match.storage_used ?? 0,
    free_shared_mailboxes: match.free_shared_mailboxes ?? 0,
    paid_shared_mailboxes: match.paid_shared_mailboxes ?? 0,
    archive: match.archive ?? false,
    suspended: match.flg_suspended ?? false,
    summary:
      `${match.organization_name}: ` +
      `${match.active_seats ?? 0} active seats ` +
      `(${match.seats_used ?? 0} used / ${match.seats_available ?? 0} available), ` +
      `${match.deactivated_seats ?? 0} deactivated, ` +
      `${match.storage_used ?? 0} storage used`,
  },
}];
